import 'package:flutter/material.dart';

abstract final class Brand {
  static const forest = Color(0xFF285A36);
  static const leaf = Color(0xFF88AF4D);
  static const earth = Color(0xFF8B6040);
  static const background = Color(0xFFF7F9F5);

  static ThemeData get theme => ThemeData(
    useMaterial3: true,
    colorScheme: ColorScheme.fromSeed(seedColor: forest, primary: forest,
      secondary: leaf, surface: Colors.white),
    scaffoldBackgroundColor: background,
    appBarTheme: const AppBarTheme(backgroundColor: background,
      surfaceTintColor: Colors.transparent),
    inputDecorationTheme: InputDecorationTheme(
      filled: true, fillColor: Colors.white,
      border: OutlineInputBorder(borderRadius: BorderRadius.circular(16)),
      enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(16),
        borderSide: const BorderSide(color: Color(0xFFD8E1D5))),
      contentPadding: const EdgeInsets.all(18),
    ),
    filledButtonTheme: FilledButtonThemeData(style: FilledButton.styleFrom(
      minimumSize: const Size(48, 56),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)))),
    navigationBarTheme: const NavigationBarThemeData(
      backgroundColor: Colors.white,
      indicatorColor: Color(0xFFE4EEDB)),
  );
}

