import 'package:flutter/foundation.dart';

/// UI-only session. No storage, authentication service, or password retention.
class MockSessionController extends ChangeNotifier {
  bool _loggedIn = false;
  String _rememberedUsername = '';
  bool get isLoggedIn => _loggedIn;
  String get rememberedUsername => _rememberedUsername;

  bool login({required String username, required String password,
    required bool rememberUsername}) {
    if (username.trim().isEmpty || password.trim().isEmpty) return false;
    _rememberedUsername = rememberUsername ? username.trim() : '';
    _loggedIn = true;
    notifyListeners();
    return true;
  }

  void logout() {
    _loggedIn = false;
    notifyListeners();
  }
}

