class SurfaceCard extends StatelessWidget {
  const SurfaceCard({super.key, required this.child, this.color = Colors.white});
  final Widget child;
  final Color color;
  @override
  Widget build(BuildContext context) => Container(
    width: double.infinity, padding: const EdgeInsets.all(24),
    decoration: BoxDecoration(color: color, borderRadius: BorderRadius.circular(24),
      border: Border.all(color: Brand.forest.withValues(alpha: .08))),
    child: child);
}

class PrimaryButton extends StatelessWidget {
  const PrimaryButton({super.key, required this.label, required this.onPressed,
    this.icon = Icons.arrow_forward_rounded});
  final String label;
  final VoidCallback onPressed;
  final IconData icon;
  @override
  Widget build(BuildContext context) => SizedBox(width: double.infinity,
    child: FilledButton.icon(onPressed: onPressed,
      icon: Icon(icon), label: Padding(padding: const EdgeInsets.symmetric(vertical: 12),
        child: Text(label))));
}

class PortalInput extends StatelessWidget {
  const PortalInput({super.key, required this.controller, required this.label,
    required this.icon, required this.validator, this.obscureText = false,
    this.suffix, this.onSubmitted, this.isPassword = false});
  final TextEditingController controller;
  final String label;
  final IconData icon;
  final String? Function(String?) validator;
  final bool obscureText;
  final bool isPassword;
  final Widget? suffix;
  final VoidCallback? onSubmitted;
  @override
  Widget build(BuildContext context) => TextFormField(
    controller: controller, obscureText: obscureText, validator: validator,
    autocorrect: false, enableSuggestions: !isPassword,
    keyboardType: isPassword ? TextInputType.visiblePassword : TextInputType.text,
    textInputAction: isPassword ? TextInputAction.done : TextInputAction.next,
    onFieldSubmitted: (_) {
      if (onSubmitted != null) { onSubmitted!(); }
      else { FocusScope.of(context).nextFocus(); }
    },
    decoration: InputDecoration(labelText: label, prefixIcon: Icon(icon),
      suffixIcon: suffix));
}

class EmployeeDetails extends StatelessWidget {
  const EmployeeDetails({super.key, this.full = false});
  final bool full;
  @override
  Widget build(BuildContext context) {
    const employee = Employee.demo;
    final entries = {
      'Employee ID': employee.id, 'Department': employee.department,
      if (full) 'Designation': employee.designation,
      if (full) 'Email': employee.email,
    };
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(employee.name, style: Theme.of(context).textTheme.titleLarge?.copyWith(
        fontWeight: FontWeight.w700)),
      const SizedBox(height: 4),
      Text(full ? 'Fictional demo employee' : employee.designation,
        style: const TextStyle(color: Brand.earth)),
      const SizedBox(height: 20),
      for (final entry in entries.entries)
        Padding(padding: const EdgeInsets.only(bottom: 16),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(entry.key, style: Theme.of(context).textTheme.labelMedium),
            const SizedBox(height: 4),
            Text(entry.value, style: Theme.of(context).textTheme.bodyLarge),
          ])),
    ]);
  }
}

