import 'package:flutter/material.dart';
import '../services/mock_session_controller.dart';
import '../theme/brand_theme.dart';
import '../widgets/common.dart';

class LoginScreen extends StatefulWidget {
  const LoginScreen({super.key, required this.session});
  final MockSessionController session;
  @override
  State<LoginScreen> createState() => _LoginScreenState();
}
class _LoginScreenState extends State<LoginScreen> {
  final _form = GlobalKey<FormState>();
  late final TextEditingController _username;
  final _password = TextEditingController();
  bool _remember = false;
  bool _hidden = true;
  @override
  void initState() {
    super.initState();
    _username = TextEditingController(text: widget.session.rememberedUsername);
    _remember = _username.text.isNotEmpty;
  }
  @override
  void dispose() { _username.dispose(); _password.dispose(); super.dispose(); }
  void _login() {
    if (!_form.currentState!.validate()) return;
    FocusScope.of(context).unfocus();
    final password = _password.text;
    _password.clear();
    widget.session.login(username: _username.text, password: password,
      rememberUsername: _remember);
  }
  @override
  Widget build(BuildContext context) => Scaffold(
    body: SafeArea(child: PageBody(child: AutofillGroup(child: Form(key: _form,
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const SizedBox(height: 20),
        const Center(child: BrandLogo(width: 240)),
        const Center(child: Text('From Earth to Heart',
          style: TextStyle(color: Brand.earth))),
        const SizedBox(height: 40),
        Text('Welcome Back', style: Theme.of(context).textTheme.headlineLarge
          ?.copyWith(fontWeight: FontWeight.w700, color: Brand.forest)),
        const SizedBox(height: 8),
        Text('FFC Employee Portal', style: Theme.of(context).textTheme.titleMedium),
        const SizedBox(height: 28),
        SurfaceCard(child: Column(children: [
          PortalInput(controller: _username, label: 'Email / Username',
            icon: Icons.person_outline_rounded,
            validator: (value) => value == null || value.trim().isEmpty
              ? 'Enter your email or username.' : null),
          const SizedBox(height: 20),
          PortalInput(controller: _password, label: 'Password',
            icon: Icons.lock_outline_rounded, isPassword: true,
            obscureText: _hidden, onSubmitted: _login,
            validator: (value) => value == null || value.trim().isEmpty
              ? 'Enter your password.' : null,
            suffix: IconButton(
              tooltip: _hidden ? 'Show password' : 'Hide password',
              onPressed: () => setState(() => _hidden = !_hidden),
              icon: Icon(_hidden ? Icons.visibility_outlined : Icons.visibility_off_outlined))),
          const SizedBox(height: 8),
          CheckboxListTile(contentPadding: EdgeInsets.zero,
            controlAffinity: ListTileControlAffinity.leading,
            title: const Text('Remember Me'),
            subtitle: const Text('Username only, for this app session'),
            value: _remember, onChanged: (value) => setState(() => _remember = value!)),
          const SizedBox(height: 16),
          PrimaryButton(label: 'Login', onPressed: _login),
        ])),
        const SizedBox(height: 24),
        const Center(child: Text('UI demo — no real authentication.',
          textAlign: TextAlign.center, style: TextStyle(color: Brand.earth))),
        const SizedBox(height: 8),
        const Center(child: Text('For Farmgenie employees',
          textAlign: TextAlign.center)),
      ]))))));
}

