import 'dart:async';
import 'package:flutter/material.dart';
import '../theme/brand_theme.dart';
import '../widgets/common.dart';

class HomeScreen extends StatefulWidget {
  const HomeScreen({super.key});
  @override
  State<HomeScreen> createState() => _HomeScreenState();
}
class _HomeScreenState extends State<HomeScreen> with WidgetsBindingObserver {
  Timer? _midnight;
  DateTime _today = DateTime.now();
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _scheduleDate();
  }
  void _scheduleDate() {
    _midnight?.cancel();
    final now = DateTime.now();
    _midnight = Timer(DateTime(now.year, now.month, now.day + 1).difference(now), () {
      if (mounted) { setState(() => _today = DateTime.now()); _scheduleDate(); }
    });
  }
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      setState(() => _today = DateTime.now());
      _scheduleDate();
    }
  }
  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this); _midnight?.cancel(); super.dispose();
  }
  @override
  Widget build(BuildContext context) {
    const modules = [
      (Icons.calendar_month_outlined, 'Attendance', 'Your workday, at a glance'),
      (Icons.inventory_2_outlined, 'Inventory', 'A fresh view of every item'),
      (Icons.qr_code_scanner_rounded, 'Barcode Scanner', 'Quick item identification'),
      (Icons.fact_check_outlined, 'Stock Audit', 'Keep every count in check'),
      (Icons.storefront_outlined, 'Store Operations', 'Everyday store essentials'),
    ];
    return PageBody(child: Column(crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('Hello, Employee', style: Theme.of(context).textTheme.headlineMedium
          ?.copyWith(fontWeight: FontWeight.w700, color: Brand.forest)),
        const SizedBox(height: 8),
        const Text('A fresh start to your workday.'),
        const SizedBox(height: 24),
        SurfaceCard(color: Brand.forest, child: Column(
          crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Icon(Icons.wb_sunny_outlined, color: Brand.leaf, size: 32),
            const SizedBox(height: 16),
            Text('Growing together,\nevery day.', style: Theme.of(context)
              .textTheme.headlineSmall?.copyWith(color: Colors.white, fontWeight: FontWeight.w600)),
            const SizedBox(height: 12),
            const Text('Welcome to Farmgenie Fresh Cart.',
              style: TextStyle(color: Colors.white)),
            const SizedBox(height: 20),
            Text(MaterialLocalizations.of(context).formatFullDate(_today),
              style: const TextStyle(color: Colors.white)),
          ])),
        const SizedBox(height: 24),
        Text('Your employee details', style: Theme.of(context).textTheme.titleLarge),
        const SizedBox(height: 12),
        const SurfaceCard(child: EmployeeDetails()),
        const SizedBox(height: 28),
        Text('Your workspace', style: Theme.of(context).textTheme.titleLarge),
        const SizedBox(height: 8),
        const Text('More ways to support your day, coming soon.'),
        const SizedBox(height: 16),
        for (final module in modules)
          Padding(padding: const EdgeInsets.only(bottom: 12),
            child: SurfaceCard(child: Column(
              crossAxisAlignment: CrossAxisAlignment.start, children: [
                Icon(module.$1, color: Brand.forest, size: 28),
                const SizedBox(height: 12),
                Text(module.$2, style: Theme.of(context).textTheme.titleMedium
                  ?.copyWith(fontWeight: FontWeight.w700)),
                const SizedBox(height: 4), Text(module.$3),
                const SizedBox(height: 12),
                Container(padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  decoration: BoxDecoration(color: const Color(0xFFEDF3E6),
                    borderRadius: BorderRadius.circular(20)),
                  child: const Text('Coming Soon',
                    style: TextStyle(color: Brand.forest, fontWeight: FontWeight.w600))),
              ]))),
        const SizedBox(height: 12),
        const Center(child: Text('From Earth to Heart',
          style: TextStyle(color: Brand.earth))),
      ]));
