import 'package:flutter/material.dart';
import '../services/mock_session_controller.dart';
import '../theme/brand_theme.dart';
import '../widgets/common.dart';

class ProfileScreen extends StatelessWidget {
  const ProfileScreen({super.key, required this.session});
  final MockSessionController session;
  Future<void> _logout(BuildContext context) async {
    final confirmed = await showDialog<bool>(context: context,
      builder: (context) => AlertDialog(
        title: const Text('Log out of FFC?'),
        content: const Text('You will return to the employee login screen.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context, false),
            child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(context, true),
            child: const Text('Logout')),
        ]));
    if (confirmed == true) session.logout();
  }
  @override
  Widget build(BuildContext context) => PageBody(child: Column(
    crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text('Your profile', style: Theme.of(context).textTheme.headlineMedium
        ?.copyWith(fontWeight: FontWeight.w700, color: Brand.forest)),
      const SizedBox(height: 8),
      const Text('Your place in the Farmgenie team.'),
      const SizedBox(height: 28),
      const Center(child: CircleAvatar(radius: 44,
        backgroundColor: Color(0xFFE4EEDB),
        child: Text('AK', style: TextStyle(fontSize: 28, color: Brand.forest)))),
      const SizedBox(height: 24),
      const SurfaceCard(child: EmployeeDetails(full: true)),
      const SizedBox(height: 24),
      PrimaryButton(label: 'Logout', icon: Icons.logout_rounded,
        onPressed: () => _logout(context)),
      const SizedBox(height: 20),
      const Center(child: Text('Employee UI demonstration',
        style: TextStyle(color: Brand.earth))),
    ]));
}
